SELECT aa.id, aa.approve_status, aa.approve_user_id, aa.approve_user_name, aa.approve_time, aa.invalid_status, aa.invalid_remark, aa.invalid_time, aa.code, aa.source_code, aa.source_type, aa.source_id, aa.accept_date, aa.purchase_code, aa.is_need_seal, aa.accept_org_id, aa.accept_org_name, aa.accept_user_id, aa.accept_user_name, aa.accept_dept_id, aa.accept_dept_name, aa.supplier_id, aa.supplier_name, aa.accept_desc, aa.create_time, aa.create_user_name, aad.id as detailId, aad.sku_no, aad.product_name, aad.accept_qty, aad.asset_card_status FROM asset_accept aa LEFT JOIN asset_accept_detail aad ON aad.main_id = aa.id AND aad.is_deleted = false WHERE ${params.sqlMap.default} AND aa.is_deleted = false
${params.permissionSql}
ORDER BY aa.create_time DESC

SELECT aa.id, aa.approve_status, aa.approve_user_id, aa.approve_user_name, aa.approve_time, aa.invalid_status, aa.invalid_remark, aa.invalid_time, aa.code, aa.source_code, aa.source_type, aa.source_id, aa.accept_date, aa.purchase_code, aa.is_need_seal, aa.accept_org_id, aa.accept_org_name, aa.accept_user_id, aa.accept_user_name, aa.accept_dept_id, aa.accept_dept_name, aa.supplier_id, aa.supplier_name, aa.accept_desc, aa.create_time, aa.create_user_name, aad.id as detailId, aad.sku_no, aad.product_name, aad.accept_qty, aad.asset_card_status FROM asset_accept aa LEFT JOIN asset_accept_detail aad ON aad.main_id = aa.id AND aad.is_deleted = false WHERE ${params.sqlMap.default} AND aa.is_deleted = false
AND aa.id IN
#{id}
${params.permissionSql}
ORDER BY aa.create_time DESC

SELECT approve_status AS tabFlag, count(*) AS count FROM asset_accept WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY approve_status
